namespace EchoEye.Core.Models;

/// <summary>
/// Represents a security alert generated by the system
/// </summary>
public class Alert
{
    /// <summary>
    /// Unique alert identifier (UUID v4)
    /// </summary>
    public string AlertId { get; set; } = string.Empty;

    /// <summary>
    /// Associated incident identifier
    /// </summary>
    public string? IncidentId { get; set; }

    /// <summary>
    /// Severity level of the alert
    /// </summary>
    public AlertSeverity Severity { get; set; }

    /// <summary>
    /// Type of alert
    /// </summary>
    public AlertType Type { get; set; }

    /// <summary>
    /// Alert title
    /// </summary>
    public string Title { get; set; } = string.Empty;

    /// <summary>
    /// Detailed description
    /// </summary>
    public string? Description { get; set; }

    /// <summary>
    /// Module that generated the alert
    /// </summary>
    public string SourceModule { get; set; } = string.Empty;

    /// <summary>
    /// Timestamp when alert was generated
    /// </summary>
    public DateTime GeneratedAt { get; set; }

    /// <summary>
    /// Timestamp when alert was acknowledged
    /// </summary>
    public DateTime? AcknowledgedAt { get; set; }

    /// <summary>
    /// User who acknowledged the alert
    /// </summary>
    public string? AcknowledgedBy { get; set; }

    /// <summary>
    /// Whether the alert has been resolved
    /// </summary>
    public bool IsResolved { get; set; }

    /// <summary>
    /// Timestamp when alert was resolved
    /// </summary>
    public DateTime? ResolvedAt { get; set; }

    /// <summary>
    /// Notes about resolution
    /// </summary>
    public string? ResolutionNotes { get; set; }

    /// <summary>
    /// Additional related data (JSON)
    /// </summary>
    public string? RelatedData { get; set; }
}

/// <summary>
/// Severity levels for alerts
/// </summary>
public enum AlertSeverity
{
    /// <summary>
    /// Informational alert
    /// </summary>
    Info = 1,

    /// <summary>
    /// Warning level alert
    /// </summary>
    Warning = 2,

    /// <summary>
    /// Error level alert
    /// </summary>
    Error = 3,

    /// <summary>
    /// Critical severity alert
    /// </summary>
    Critical = 4
}

/// <summary>
/// Types of alerts that can be generated
/// </summary>
public enum AlertType
{
    /// <summary>
    /// Suspicious file modification detected
    /// </summary>
    FileModification = 1,

    /// <summary>
    /// Decoy file interaction detected
    /// </summary>
    DecoyInteraction = 2,

    /// <summary>
    /// Suspicious process activity
    /// </summary>
    ProcessSuspicious = 3,

    /// <summary>
    /// Network anomaly detected
    /// </summary>
    NetworkAnomaly = 4,

    /// <summary>
    /// Recovery operation failure
    /// </summary>
    RecoveryFailure = 5,

    /// <summary>
    /// System health issue
    /// </summary>
    SystemHealth = 6,

    /// <summary>
    /// Configuration change detected
    /// </summary>
    ConfigurationChange = 7
}
